sys_script_fix.script:
//Find all duplicates

//---------------------------------------------------------------------------------------------------------------------------------------------------------------
//Find duplicates
var dupes = getDuplicateValues('sys_user', 'u_user_principal_name');
gs.info(dupes);

var userArr = [];

for (var i = 0; i < dupes.length; i++) {
    var duplicates = new GlideRecord('sys_user');
    //duplicates.addEncodedQuery('u_user_principal_nameISNOTEMPTY^active=true');
    //duplicates.addEncodedQuery('u_user_principal_nameISNOTEMPTY');
    //duplicates.addQuery('u_user_principal_name', '0014853211@ICE.DHS.GOV');
    duplicates.addEncodedQuery('u_user_principal_name='+dupes[i]);
    duplicates.addQuery('sys_updated_by', 'ldap_user'); //double check username -------------------------------------
    duplicates.addQuery('email', 'DOESNOTCONTAIN', '@associates');
    duplicates.addActiveQuery();
    //duplicates.setLimit(100);
    duplicates.query();
    while (duplicates.next()){
      userArr.push(duplicates.sys_id+'');
    }
}

gs.info(userArr.length);

var allUsers = [];

var user1 = new GlideRecord('sys_user');
user1.addQuery('sys_id', 'IN', userArr);
user1.query();

while (user1.next()) {
    var user2 = new GlideRecord('sys_user');
    user2.addQuery('sys_id', "!=",  user1.sys_id);
    user2.addQuery('u_user_principal_name', user1.u_user_principal_name);
    user2.addQuery('sys_id', "IN", userArr);
    user2.query();
    while (user2.next()){
        var returnedUsers = compareUser(user1.sys_id, user2.sys_id);
        allUsers.push(returnedUsers);
    }
}


